// Lottie, loaded on demand (the light player: ~60 KB gzipped) and only once.
// Animations live in public/lottie (generated by scripts/lottie.mjs).

import type { AnimationItem } from 'lottie-web'

type Lottie = typeof import('lottie-web/build/player/lottie_light')['default']
let lib: Promise<Lottie> | null = null
const data = new Map<string, Promise<object>>()

function load(): Promise<Lottie> {
  return (lib ||= import('lottie-web/build/player/lottie_light').then(m => m.default))
}

function animationData(name: string): Promise<object> {
  let p = data.get(name)
  if (!p) {
    p = fetch(`/lottie/${name}.json`).then(r => r.json() as Promise<object>)
    data.set(name, p)
  }
  return p
}

export interface PlayOptions {
  loop?: boolean
  autoplay?: boolean
}

/** Mounts an animation into `el`; resolves once it is ready (null if Lottie can't load). */
export async function play(el: Element, name: string, opts: PlayOptions = {}): Promise<AnimationItem | null> {
  try {
    const [lottie, animationDataJson] = await Promise.all([load(), animationData(name)])
    return lottie.loadAnimation({
      container: el,
      renderer: 'svg',
      loop: opts.loop ?? true,
      autoplay: opts.autoplay ?? true,
      animationData: animationDataJson,
      rendererSettings: { preserveAspectRatio: 'xMidYMid meet', progressiveLoad: true },
    })
  } catch {
    return null
  }
}

/** Every [data-lottie] on the page that is still empty. */
export function mountAll(root: ParentNode = document) {
  root.querySelectorAll<HTMLElement>('[data-lottie]').forEach(el => {
    // Lazy ones are mounted by whoever shows them (the demo's guiding hand).
    if (el.dataset.lottieMounted || el.hasAttribute('data-lottie-lazy')) return
    el.dataset.lottieMounted = '1'
    void play(el, el.dataset.lottie!)
  })
}
